// Lazy: no socket is opened until the first query runs.

// knexfile.cjs
// .cjs on purpose: the CLI loads this file with require, and a
// package.json with "type": "module" makes a plain .js file an ES module.
require('dotenv/config');

const base = {
  client: 'mysql2',
  connection: {
    host: process.env.DB_HOST ?? 'localhost',
    port: Number(process.env.DB_PORT ?? 3306),
    user: process.env.DB_USER ?? 'root',
    password: process.env.DB_PASSWORD ?? '',
    database: process.env.DB_NAME ?? 'bookings',
  },
  dateStrings: true,
  migrations: { directory: './db/migrations', tableName: 'knex_migrations' },
  seeds: { directory: './db/seeds' },
};

module.exports = {
  development: { ...base, pool: { min: 0, max: 10 } },
  production: { ...base, pool: { min: 2, max: 20 }, asyncStackTraces: false },
};

const db = knex({
  client: 'mysql2',
  connection: { host: 'localhost', database: 'bookings' },
  pool: {
    min: 0,                        // idle sockets kept open
    max: 10,                       // hard cap for this process
    acquireTimeoutMillis: 10_000,  // fail instead of queueing forever
    idleTimeoutMillis: 30_000,     // close a socket unused this long, down to min
    // Runs on every new socket. done(err) finishes the setup.
    afterCreate(conn, done) {
      conn.query("SET time_zone = '+00:00'", done);
    },
  },
});

// Ten app processes with max: 10 need 100 slots in MySQL max_connections.

// scripts/report.js
import db from '../db.js';

try {
  const [{ total }] = await db('hotels').count('* as total');
  console.log('hotels:', Number(total));
} finally {
  await db.destroy();
}

// In a server, close the HTTP listener first, then the pool:
// server.close(async () => { await db.destroy(); process.exit(0); });

// rows: [{ id: 1, name: 'Danube View', stars: 4 }, ...]
const rows = await db('hotels').select('id', 'name', 'stars');

// Aliases: the object key becomes the column name in the result.
const owners = await db('hotels as h')
  .join('customers as c', 'c.email', 'h.owner_email')
  .select({ hotel: 'h.name', owner: 'c.last_name' });

// select('*') sends every column, including a 500 character image URL
// and a TEXT description, on every list request.

await db('hotels').where('city', 'Budapest');             // city = 'Budapest'
await db('hotels').where('stars', '>=', 4);               // stars >= 4
await db('hotels').where({ city: 'Budapest', stars: 4 }); // both, joined with AND

// Lists and NULL need their own methods.
await db('bookings').whereIn('hotel_id', [1, 2, 3]);
await db('customers').whereNull('phone');
await db('bookings').whereBetween('start_date', ['2025-07-01', '2025-07-31']);

// Grouping: without the callback the OR escapes every other condition.
await db('hotels')
  .where('stars', '>=', 4)
  .where(function () {
    this.where('city', 'Budapest').orWhere('city', 'Debrecen');
  });
// where stars >= 4 and (city = 'Budapest' or city = 'Debrecen')

// First page of the cheapest hotels in one city.
const page1 = await db('hotels')
  .where('city', 'Budapest')
  .orderBy('stars', 'asc')
  .limit(10)
  .offset(0);

// Two keys, so ties on stars fall back to the name.
const ranked = await db('hotels').orderBy([
  { column: 'stars', order: 'desc' },
  { column: 'name', order: 'asc' },
]);

// Custom order, bound as values.
const byCity = await db('hotels').orderByRaw('FIELD(city, ?, ?)', ['Budapest', 'Eger']);

const hotel = await db('hotels').where('id', 1).first();
if (!hotel) {
  // undefined, not an empty object: check before reading a column.
  return res.status(404).json({ error: 'Hotel not found' });
}
console.log(hotel.name);

// One column only: the value itself, or undefined.
const name = await db('hotels').where('id', 1).first('name');

// rows: [{ total: 3 }], sometimes [{ total: '3' }]
const [row] = await db('hotels').count('* as total');
const total = Number(row.total);

// Unique guests, not bookings. Without distinct a join multiplies rows.
const [guests] = await db('bookings').countDistinct('customer_email as guests');

// Counting per group.
const perHotel = await db('bookings')
  .select('hotel_id')
  .count('* as booked')
  .groupBy('hotel_id');

// One row: destructure the generated id.
const [hotelId] = await db('hotels').insert({
  city: 'Eger',
  name: 'Hill House',
  description: 'Six rooms above a bakery.',
  stars: 3,
  owner_email: 'anna.kovacs@example.com',
  image: null,
});
console.log(hotelId); // 4

// Many rows in one statement. MySQL reports the first generated id only.
await db('bookings').insert([
  { customer_email: 'anna.kovacs@example.com', hotel_id: 1, start_date: '2025-07-01', end_date: '2025-07-05', adults: 2, children: 1, boylovers: 0 },
  { customer_email: 'ben.nagy@example.com', hotel_id: 1, start_date: '2025-07-10', end_date: '2025-07-12', adults: 1, children: 0, boylovers: 0 },
]);

const affected = await db('hotels').where('id', 1).update({ stars: 4 });
console.log(affected); // 1

// Arithmetic happens in the server, so concurrent requests both count.
await db('hotels').where('id', 1).increment('stars', 1);
await db('hotels').where('id', 1).decrement('stars', 1);

// A patch built from a request body needs a fixed key list.
const allowed = ['city', 'name', 'description', 'stars', 'image'];
const changes = Object.fromEntries(
  Object.entries(req.body).filter(([key]) => allowed.includes(key))
);
if (Object.keys(changes).length > 0) {
  await db('hotels').where('id', req.params.id).update(changes);
}

const removed = await db('bookings')
  .where({ customer_email: 'ben.nagy@example.com', hotel_id: 1 })
  .del();
console.log(removed); // 1

// A hotel that still has bookings raises ER_ROW_IS_REFERENCED_2,
// because the foreign key is ON DELETE RESTRICT.
try {
  await db('hotels').where('id', 1).del();
} catch (error) {
  if (error.code === 'ER_ROW_IS_REFERENCED_2') {
    console.log('Delete the bookings first.');
  }
}

// Empty the table and reset the auto increment. DDL, so no rollback.
await db('hotels').truncate();

// Warning on MySQL: .returning() is not supported and has no effect.
const result = await db('hotels')
  .insert({ city: 'Eger', name: 'Hill House' })
  .returning('id');
// result is still [insertId], not [{ id: 4 }]

// Portable pattern: insert, then read the row by its id.
const [id] = await db('hotels').insert({
  city: 'Eger',
  name: 'Hill House',
  stars: 3,
  owner_email: 'anna.kovacs@example.com',
});
const created = await db('hotels').where('id', id).first();

// For an update, read inside the same transaction so nothing slips between.
await db.transaction(async (trx) => {
  await trx('hotels').where('id', id).update({ stars: 4 });
  const row = await trx('hotels').where('id', id).first();
  return row;
});

// One guest books one hotel once, so the primary key is
// (customer_email, hotel_id). A repeated POST moves the dates.
await db('bookings')
  .insert({
    customer_email: 'ben.nagy@example.com',
    hotel_id: 1,
    start_date: '2025-09-01',
    end_date: '2025-09-04',
    adults: 2,
    children: 0,
    boylovers: 0,
  })
  .onConflict()
  .merge(['start_date', 'end_date', 'adults', 'children', 'boylovers']);

// Insert or do nothing. Useful for a seed that may run twice.
await db('customers')
  .insert({ email: 'cara.szabo@example.com', first_name: 'Cara', last_name: 'Szabo' })
  .onConflict()
  .ignore();

// Bookings with the guest name and image the frontend renders.
const rows = await db('bookings as b')
  .join('customers as c', 'c.email', 'b.customer_email')
  .select(
    'b.customer_email',
    'b.hotel_id',
    'b.start_date',
    'b.end_date',
    'b.adults',
    'b.children',
    'c.first_name',
    'c.last_name',
    'c.image as customer_image'
  )
  .where('b.hotel_id', 1)
  .orderBy('b.start_date', 'asc');

// Three tables, all columns qualified.
const detailed = await db('bookings as b')
  .join('customers as c', 'c.email', 'b.customer_email')
  .join('hotels as h', 'h.id', 'b.hotel_id')
  .select('c.last_name', 'h.name', 'h.city', 'b.start_date');

// Hotels with their booking count, including hotels nobody booked.
const rows = await db('hotels as h')
  .leftJoin('bookings as b', 'b.hotel_id', 'h.id')
  .select('h.id', 'h.name')
  .count('b.customer_email as guests')
  .groupBy('h.id', 'h.name');

// rows: [{ id: 1, name: 'Danube View', guests: 2 }, { id: 3, name: 'City Loft', guests: 0 }]

// A filter on the right side belongs in the join condition.
const withRooms = await db('hotels as h')
  .leftJoin('bookings as b', function () {
    this.on('b.hotel_id', 'h.id').andOn('b.end_date', '>', db.raw('?', ['2025-07-01']));
  })
  .select('h.name', 'b.start_date');

const perHotel = await db('bookings')
  .select('hotel_id')
  .count('* as booked')
  .sum('adults as adults')
  .groupBy('hotel_id')
  .havingRaw('count(*) > ?', [1])
  .orderBy('booked', 'desc');

// rows: [{ hotel_id: 1, booked: 2, adults: '3' }]

// Grouping by a joined column needs it in the group list too.
const byCity = await db('hotels as h')
  .join('bookings as b', 'b.hotel_id', 'h.id')
  .select('h.city')
  .countDistinct('b.customer_email as guests')
  .groupBy('h.city');

export async function book({ email, hotelId, start, end }) {
  return db.transaction(async (trx) => {
    // forUpdate locks the row until this transaction ends.
    const hotel = await trx('hotels').where('id', hotelId).forUpdate().first();
    if (!hotel) throw Object.assign(new Error('Hotel not found'), { status: 404 });

    const clash = await trx('bookings')
      .where('hotel_id', hotelId)
      .where('start_date', '<', end)
      .where('end_date', '>', start)
      .first();
    if (clash) throw Object.assign(new Error('Dates taken'), { status: 409 });

    await trx('bookings').insert({
      customer_email: email,
      hotel_id: hotelId,
      start_date: start,
      end_date: end,
      adults: 1,
      children: 0,
      boylovers: 0,
    });

    return trx('bookings').where({ customer_email: email, hotel_id: hotelId }).first();
  });
}

// Destructure the rows; the second item is the field metadata.
const [rows] = await db.raw(
  'select hotel_id, count(*) as booked from bookings group by hotel_id'
);
console.log(rows[0].booked);

// Bound values, never interpolation.
const [matched] = await db.raw(
  'select id, name from hotels where city = ? and stars >= ?',
  ['Budapest', 4]
);

// Raw expression inside a builder, for functions knex does not model.
const owners = await db('hotels as h')
  .join('customers as c', 'c.email', 'h.owner_email')
  .select('h.name', db.raw("concat(c.first_name, ' ', c.last_name) as owner"));

// Expression on the left side, value bound on the right.
await db('hotels').whereRaw('LOWER(name) LIKE ?', ['%view%']);

// Identifier binding. Without ?? MySQL compares the column to the text 'h.stars'.
await db('hotels as h').whereRaw('?? = ?', ['h.stars', 4]);

// Careful: the % stays a wildcard, so a user typing % matches everything.
const term = req.query.q ?? '';
const rows = await db('hotels').whereRaw('name like ?', [`%${term}%`]);

// Bound list, built from the array length.
await db('hotels').whereRaw('id in (?, ?, ?)', [1, 2, 3]);

exports.up = async function up(knex) {
  await knex.schema.createTable('hotels', (table) => {
    table.increments('id').primary();
    table.string('city', 80).notNullable();
    table.string('name', 120).notNullable();
    table.text('description').nullable();
    table.tinyint('stars').notNullable().defaultTo(0);
    table.string('owner_email', 120).notNullable();
    table.string('image', 500).nullable();
    table.foreign('owner_email').references('email').inTable('customers')
      .onUpdate('CASCADE').onDelete('RESTRICT');
    table.check('stars between 0 and 5', [], 'chk_hotels_stars');
    table.engine('InnoDB');
    table.charset('utf8mb4');
  });
};

exports.down = async function down(knex) {
  await knex.schema.dropTableIfExists('hotels');
};

